package com.danil.blackswordsman;
import java.io.*;
public final class ExportV8Models {public static void main(String[] args)throws Exception{File dir=new File("build/v8-model-qa");dir.mkdirs();for(int id=0;id<12;id++){int[] types={-1,-1,-1,-1,GameWorld.FLESH_HOUND,GameWorld.SNAKE_BARON,GameWorld.COUNT_APOSTLE,GameWorld.TUSK_BOAR,GameWorld.MIRE_SPITTER,GameWorld.WALKER,GameWorld.ALIEN,GameWorld.GROVE_WARDEN};GameWorld.Actor a=new GameWorld.Actor();a.type=types[id];a.height=2.1f;a.radius=.52f;a.colorR=.12f;a.colorG=.13f;a.colorB=.15f;if(a.type>=0)EnemyDefinitions.apply(a,a.type,1);a.speed=5;a.grounded=true;a.motionReady=true;a.yaw=.15f;if(id==1){a.animationSpeed=1;a.gaitPhase=1.4f;}if(id==2){a.attackTime=.40f;a.attackDuration=.82f;a.strikeAt=.5f;a.attackKind=5;a.attackBlend=1;}if(id==3){a.flying=true;a.grounded=false;}SkinGeometry data=new SkinGeometry(a,true);CharacterSkeleton.Pose p=new CharacterSkeleton.Pose();CharacterSkeleton.sample(a,.3f,p);float[] palette=new float[256];data.palette(p,a.yaw,palette);float[] v=data.vertices.clone();for(int i=0;i<v.length;i+=16){float x=v[i],y=v[i+1],z=v[i+2],nx=v[i+3],ny=v[i+4],nz=v[i+5];for(int row=0;row<3;row++){float pos=0,n=0;for(int part=0;part<2;part++){int o=(int)v[i+11+part]*16;float weight=v[i+13+part];pos+=(palette[o+row]*x+palette[o+4+row]*y+palette[o+8+row]*z+palette[o+12+row])*weight;n+=(palette[o+row]*nx+palette[o+4+row]*ny+palette[o+8+row]*nz)*weight;}v[i+row]=pos;v[i+3+row]=n;}v[i+6]*=a.colorR;v[i+7]*=a.colorG;v[i+8]*=a.colorB;}File dest=new File(dir,id+".bin"),part=new File(dest+".part");DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(part)));out.writeInt(v.length);out.writeInt(data.indices.length);for(float f:v)out.writeFloat(f);for(short q:data.indices)out.writeShort(q);out.close();if(!part.renameTo(dest))throw new IOException("Rename");}}}
